'use strict';
let bulkImportFilms=[],bulkImportJob=0;
const IMPORT_COLUMNS=['id','title','year','country','runtime','genres','director','screenplay','cinematography','music','cast','watchedOn','rating','story','visuals','performances','impact','review','poster'];
function parseCsvRows(text){text=String(text).replace(/^\uFEFF/,'');const first=text.split(/\r?\n/,1)[0],delimiter=first.includes('\t')?'\t':first.includes(';')&&!first.includes(',')?';':',';const rows=[];let row=[],cell='',quoted=false,closed=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'){if(text[i+1]==='"'){cell+='"';i++}else{quoted=false;closed=true}}else cell+=c;continue}if(c==='"'){if(cell||closed)throw Error('CSV có dấu nháy sai vị trí.');quoted=true}else if(c===delimiter){row.push(cell);cell='';closed=false}else if(c==='\r'||c==='\n'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';closed=false}else{if(closed&&!/\s/.test(c))throw Error('CSV có nội dung sau dấu nháy đóng.');if(!closed)cell+=c}}if(quoted)throw Error('CSV thiếu dấu nháy đóng.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(!rows.length)throw Error('CSV trống.');const headers=rows.shift().map(h=>h.trim());if(!headers.includes('title'))throw Error('CSV cần có cột title.');if(new Set(headers).size!==headers.length)throw Error('CSV có tên cột trùng.');const unknown=headers.filter(h=>!IMPORT_COLUMNS.includes(h));if(unknown.length)throw Error('Cột CSV không hỗ trợ: '+unknown.join(', '));return rows.map((cells,i)=>{if(cells.length!==headers.length)throw Error('Dòng CSV '+(i+2)+' thiếu hoặc thừa cột.');return Object.fromEntries(headers.map((h,j)=>[h,cells[j].trim()]))})}
function importId(title,year){const slug=String(title).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/gi,'d').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80);if(!slug)throw Error('Tên phim này cần thêm cột id bằng chữ Latin hoặc số.');return slug+(year?'-'+year:'')}
function importRecord(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw)||typeof raw.title!=='string'||!raw.title.trim())throw Error('Mỗi phim cần có title.');const list=v=>Array.isArray(v)?v:String(v||'').split('|').map(s=>s.trim()).filter(Boolean);const ratings={};for(const[k]of criteria){const value=raw.ratings?.[k]??raw[k]??raw.rating;ratings[k]=value===undefined||value===null||value===''?null:Number(value);if(ratings[k]!==null&&(!Number.isInteger(ratings[k])||ratings[k]<1||ratings[k]>5))throw Error(raw.title+': điểm phải là số nguyên 1–5 hoặc để trống.')}const year=raw.year===''||raw.year===undefined||raw.year===null?null:Number(raw.year);if(year!==null&&(!Number.isInteger(year)||year<1888||year>2100))throw Error(raw.title+': năm phát hành không hợp lệ.');const runtime=raw.runtime===''||raw.runtime===undefined||raw.runtime===null?null:Number(raw.runtime);if(runtime!==null&&(!Number.isInteger(runtime)||runtime<1||runtime>2000))throw Error(raw.title+': thời lượng không hợp lệ.');let watches=raw.watches??(raw.watchedOn?[{date:String(raw.watchedOn)}]:[]);if(!Array.isArray(watches)||watches.some(w=>!w||typeof w!=='object'||w.date&&(!validDate(w.date)||new Date(w.date+'T00:00:00Z').toISOString().slice(0,10)!==w.date)))throw Error(raw.title+': ngày xem cần là YYYY-MM-DD.');if(raw.poster&&!safeImage(raw.poster))throw Error(raw.title+': poster cần là URL ảnh hợp lệ.');return normalize({...raw,id:raw.id||importId(raw.title,year),year,runtime,genres:list(raw.genres),cast:list(raw.cast),ratings,watches,updatedAt:raw.updatedAt||new Date().toISOString()})}
function parseImportText(name,text){let records;if(/\.md$/i.test(name))return[parseMd(text)];if(/\.csv$/i.test(name))records=parseCsvRows(text);else if(/\.json$/i.test(name)){const data=JSON.parse(text.replace(/^\uFEFF/,''));records=Array.isArray(data)?data:data?.films;if(!Array.isArray(records))throw Error('JSON cần là danh sách phim hoặc object có films.')}else throw Error('Chỉ hỗ trợ .md, .csv và .json.');return records.map(importRecord)}
function validateImportBatch(records){if(!records.length)throw Error('Không tìm thấy phim trong file.');if(records.length>1000)throw Error('Mỗi lần nhập tối đa 1.000 phim.');const seen=new Set();for(const film of records){if(seen.has(film.id))throw Error('ID bị trùng ngay trong lần nhập này: '+film.id);seen.add(film.id)}return records}
function planImport(existing,incoming,replace=false){const map=new Map(existing.map(f=>[f.id,f]));let added=0,replaced=0,skipped=0;for(const film of incoming){if(map.has(film.id)){if(!replace){skipped++;continue}replaced++}else added++;map.set(film.id,film)}return{films:[...map.values()],added,replaced,skipped}}
function openBulkImport(){if(!requireOwner())return;if($('#settings').open)$('#settings').close();bulkImportJob++;bulkImportFilms=[];$('#bulkFiles').value='';$('#replaceImported').checked=false;$('#bulkImportStatus').textContent='';$('#bulkImportStatus').className='bulk-status';$('#bulkImportPreview').innerHTML='';$('#confirmBulkImport').disabled=true;$('#bulkImportDialog').showModal()}
function renderBulkPreview(){const plan=planImport(films,bulkImportFilms,$('#replaceImported').checked),ids=new Set(films.map(f=>f.id));$('#bulkImportStatus').textContent=`${bulkImportFilms.length} phim · ${plan.added} phim mới · ${plan.replaced} thay thế · ${plan.skipped} bỏ qua`;$('#bulkImportPreview').innerHTML='<table><thead><tr><th>Phim</th><th>Năm</th><th>Điểm</th><th>Trạng thái</th></tr></thead><tbody>'+bulkImportFilms.slice(0,50).map(f=>`<tr><td>${esc(f.title)}</td><td>${f.year||'—'}</td><td>${scoreText(f)}</td><td class="${ids.has(f.id)?'import-existing':''}">${ids.has(f.id)?($('#replaceImported').checked?'Thay thế':'Bỏ qua'):'Thêm mới'}</td></tr>`).join('')+'</tbody></table>'+(bulkImportFilms.length>50?'<p class="bulk-preview-note">Hiển thị 50 phim đầu. Số lượng nhập ở phía trên tính toàn bộ danh sách.</p>':'');$('#confirmBulkImport').disabled=!bulkImportFilms.length||!plan.added&&!plan.replaced;$('#confirmBulkImport').textContent=`Import ${plan.added+plan.replaced} phim`}
$('#bulkImportBtn').onclick=openBulkImport;$('#chooseBulkFiles').onclick=()=>$('#bulkFiles').click();$('#replaceImported').onchange=()=>{if(bulkImportFilms.length)renderBulkPreview()};
$('#bulkFiles').onchange=async e=>{if(!requireOwner())return;const files=[...e.target.files],job=++bulkImportJob;bulkImportFilms=[];$('#confirmBulkImport').disabled=true;$('#bulkImportPreview').innerHTML='';$('#bulkImportStatus').className='bulk-status';$('#bulkImportStatus').textContent='Đang kiểm tra file…';try{if(files.reduce((sum,f)=>sum+f.size,0)>20*1024*1024)throw Error('Tổng dung lượng mỗi lần nhập tối đa 20 MB.');const records=[];for(const file of files){if(file.size>4*1024*1024)throw Error(file.name+' vượt quá 4 MB.');try{records.push(...parseImportText(file.name,await file.text()))}catch(err){throw Error(file.name+': '+err.message)}}validateImportBatch(records);if(job!==bulkImportJob||!ownerAuthorized)return;bulkImportFilms=records;renderBulkPreview()}catch(err){if(job!==bulkImportJob)return;$('#bulkImportStatus').className='bulk-status error';$('#bulkImportStatus').textContent=err.message}};
$('#confirmBulkImport').onclick=()=>{if(!requireOwner()||!bulkImportFilms.length)return;const plan=planImport(films,bulkImportFilms,$('#replaceImported').checked);if(!persist(plan.films))return;bulkImportJob++;$('#bulkImportDialog').close();route();toast(`Đã nhập ${plan.added} phim mới, thay thế ${plan.replaced}. Bấm Đồng bộ để lưu GitHub.`)};
$('#downloadCsvTemplate').onclick=()=>{const fields=['id','title','year','country','runtime','genres','cast','watchedOn','rating','review','poster'];const rows=[['example-film','Tên phim của bạn','2026','Vietnam','120','Drama|Comedy','Diễn viên A|Diễn viên B','2026-11-14','4','Một đoạn review ngắn (không bắt buộc).','']];const quote=s=>'"'+String(s).replace(/"/g,'""')+'"';download(new Blob(['\uFEFF'+[fields,...rows].map(row=>row.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'pauls-movie-log-template.csv')};
